    var keys=['employees','payrollEmployees','acaciaPayrollEmployees'];
    for(var i=0;i<keys.length;i++){try{var a=JSON.parse(localStorage.getItem(keys[i])||'null');if(Array.isArray(a)&&a.length)return a;}catch(e){}}
