  function selectedBudget(){var e=document.getElementById('actualBudgetPicker');return e?e.value:''}
  function selectedDepartment(){var e=document.getElementById('actualCategory');return e?e.value:''}
  function chosenLine(){var e=document.getElementById('actualAccount');if(!e||e.selectedIndex<0)return null;var i=e.options[e.selectedIndex].getAttribute('data-budget-index');return i==null||i===''?null:rows()[Number(i)]||null}
  function clearMeta(){['actualPeriod','actualYear'].forEach(function(id){var e=document.getElementById(id);if(e)e.value=''});var m=document.getElementById('actualMonth');if(m){m.innerHTML='<option value="">Select a budget line first</option>';m.disabled=true}var q=document.getElementById('actualQuarter');if(q)q.innerHTML='<option value=""></option>'}
  function fillBudgets(){var e=document.getElementById('actualBudgetPicker');if(!e)return;var old=e.value,bs=rows(),names=[];bs.forEach(function(b){var n=nameOf(b);if(names.indexOf(n)<0)names.push(n)});e.innerHTML='<option value="">— Select an added budget —</option>'+names.map(function(n){return '<option value="'+esc(n)+'">'+esc(n)+'</option>'}).join('');if(names.indexOf(old)>=0)e.value=old;fillDepartments();}
  function fillDepartments(){var e=document.getElementById('actualCategory');if(!e)return;var old=e.value,b=selectedBudget(),list=rows().filter(function(x){return nameOf(x)===b}),deps=[];list.forEach(function(x){var d=String(x.department||'').trim();if(d&&deps.indexOf(d)<0)deps.push(d)});e.innerHTML='<option value="">— Select department —</option>'+deps.map(function(d){return '<option value="'+esc(d)+'">'+esc(d)+'</option>'}).join('');if(deps.indexOf(old)>=0)e.value=old;fillLines();}
  function fillLines(){var e=document.getElementById('actualAccount');if(!e)return;var old=e.value,b=selectedBudget(),d=selectedDepartment(),bs=rows(),opts=[];bs.forEach(function(x,i){if(nameOf(x)===b&&String(x.department||'')===d&&lineOf(x))opts.push({b:x,i:i})});e.innerHTML='<option value="">— Select a budget line in this department —</option>'+opts.map(function(x){return '<option value="'+esc(lineOf(x.b))+'" data-budget-index="'+x.i+'">'+esc(lineOf(x.b))+'</option>'}).join('');if(opts.some(function(x){return lineOf(x.b)===old}))e.value=old;applyLine();}
  function rangeLabel(m,cycle){var label=String(m.month==null?'':m.month);if(cycle==='Quarterly'&&/^Q[1-4]$/i.test(label))return label.toUpperCase();if(cycle==='Annual')return String(m.year||label);return label+(m.year?' '+m.year:'')}
  function applyLine(){var b=chosenLine();if(!b){clearMeta();return}var cycle=String(b.period||b.type||b.periodCycle||'Monthly'),p=document.getElementById('actualPeriod'),y=document.getElementById('actualYear'),m=document.getElementById('actualMonth'),q=document.getElementById('actualQuarter');if(p)p.value=cycle;
    var months=Array.isArray(b.months)?b.months:[],years=Array.from(new Set(months.map(function(x){return Number(x.year)||Number(b.year)||new Date().getFullYear()})));
    var options=[];months.forEach(function(x){var v=String(x.month==null?'':x.month);if(cycle==='Quarterly'&&!/^Q[1-4]$/i.test(v)){var pr=String(x.period||'');var mm=/^Q[1-4]$/i.test(pr)?pr.toUpperCase():'';if(!mm)return;v=mm}if(cycle==='Annual')v=String(x.year||b.year||v);var yr=Number(x.year)||Number(b.year)||new Date().getFullYear();var key=v+'|'+yr;if(!options.some(function(o){return o.key===key}))options.push({key:key,value:v,year:yr,label:rangeLabel({month:v,year:yr},cycle)})});
    if(!options.length){var fy=Number(b.year)||new Date().getFullYear();options=[{key:String(fy)+'|'+fy,value:cycle==='Annual'?String(fy):'',year:fy,label:cycle==='Annual'?String(fy):'No timeframe set on budget'}]}
    if(m){m.innerHTML=options.map(function(o){return '<option value="'+esc(o.key)+'">'+esc(o.label)+'</option>'}).join('');m.disabled=options.length<=1}
    var first=options[0];if(first){if(y)y.value=String(first.year);if(cycle==='Quarterly'&&q)q.innerHTML='<option value="'+esc(first.value)+'">'+esc(first.value)+'</option>';if(m)m.value=first.key}
    if(m)m.onchange=function(){var a=m.value.split('|');if(y)y.value=a[1]||'';if(cycle==='Quarterly'&&q)q.innerHTML='<option value="'+esc(a[0])+'">'+esc(a[0])+'</option>'};
  }
  window.acxActualBudgetGroupChanged=function(){var d=document.getElementById('actualCategory');if(d)d.value='';fillDepartments()};
  window.acxActualDepartmentChanged=fillLines;
  window.acxActualBudgetChanged=applyLine;
  window.acxRenderExpenditureSelectors=fillBudgets;
  // Stage against the timeframe explicitly allocated to the selected budget line.
