/* ===== budget-profitability-reports.js ===== */
;(function(){
 'use strict';
 var defs=[
  {id:'acxRptDeptBudgetActual',name:'Department Budget vs Actual Report',cols:['Department','Department Budget','Total Allocations','Actual Expenditure','Remaining Balance','Variance'],kind:'dept'},
  {id:'acxRptBudgetActual',name:'Budget vs Actual',cols:['Project','Department','Allocated Budget','Actual Expenditure','Balance','Variance'],kind:'project'},
  {id:'acxRptBudgetExpenditure',name:'Budget Expenditure',cols:['Date','Budget Line','Department','Description','Fiscal Year','Actual Amount'],kind:'expenditure'},
  {id:'acxRptBudgetAllocation',name:'Budget Allocation Report',cols:['Budget Name','Original Budget','Department Allocations','Project Allocations','Unallocated Balance'],kind:'allocation'},
  {id:'acxRptBudgetRevision',name:'Budget Revision Report',cols:['Date','Budget / Allocation','Department','Before','After','Difference','Reason','Revised By'],kind:'revision'},
  {id:'acxRptBudgetTransfer',name:'Budget Transfer Report',cols:['Date','From Department','To Department','Amount','Reason','Approval Status'],kind:'transfer'},
  {id:'acxRptBudgetApproval',name:'Budget Approval Register',cols:['Budget Name','Department','Budget Amount','Status','Approver','Approval Date'],kind:'approval'},
  {id:'acxRptSpendingLimits',name:'Department Spending Limits Report',cols:['Department','Spending Limit','Actual Spending','Remaining Limit','Status'],kind:'limits'}
 ];
 var esc=function(v){return String(v==null?'':v).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})};
 var n=function(v){return Number(v)||0}, money=function(v){return 'KES '+n(v).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})};
 function arr(key){try{var x=JSON.parse(localStorage.getItem(key)||'[]');return Array.isArray(x)?x:[]}catch(e){return []}}
 function records(name){try{if(name==='budgets'&&typeof budgets!=='undefined'&&Array.isArray(budgets))return budgets;if(name==='actuals'&&typeof actuals!=='undefined'&&Array.isArray(actuals))return actuals}catch(e){}return arr(name)}
 function total(r){return (r.months||[]).reduce(function(s,m){return s+n(m.amount)},0)+n(r.amount||r.totalAmount||r.budgetAmount||r.allocation)}
 function actualDepartment(a){return a.department||a.category||a.departmentName||''}
 function getActualRows(){return records('actuals')}
 function getBudgetRows(){return records('budgets')}
 function sum(list){return list.reduce(function(s,r){return s+total(r)},0)}
 function dataRows(kind){var bs=getBudgetRows(),as=getActualRows(),out=[];
  if(kind==='dept'){var ds=arr('acxBudgetDepartments'),names=[].concat(ds.map(function(d){return d.name}),bs.map(function(b){return b.department}),as.map(actualDepartment)).filter(Boolean);names=[...new Set(names)];out=names.map(function(d){var b=bs.filter(function(x){return x.department===d}),a=as.filter(function(x){return actualDepartment(x)===d}),budget=sum(b),spent=sum(a),alloc=b.reduce(function(s,x){return s+n(x.departmentAllocation||x.allocatedAmount)},0);return [d,money(budget),money(alloc),money(spent),money(budget-spent),money(budget-spent)]});}
  if(kind==='project'){var ps=arr('acxBudgetProjects').concat(arr('budgetProjects'),arr('projects'));out=ps.map(function(p){var dept=p.department||p.departmentName||'',name=p.name||p.projectName||p.title||'Project',budget=n(p.budget||p.allocatedBudget||p.allocation),spent=sum(as.filter(function(a){return (a.project||a.projectName)===name&&actualDepartment(a)===dept}));return [name,dept,money(budget),money(spent),money(budget-spent),money(budget-spent)]});}
  if(kind==='expenditure'){as.forEach(function(a){var months=Array.isArray(a.months)&&a.months.length?a.months:[a];months.forEach(function(m){var amount=n(m.amount||a.amount||a.actualAmount);out.push([m.date||a.date||m.month||a.month||'',a.account||a.budgetLine||a.name||'',actualDepartment(a),a.description||a.reason||a.departmentDescription||'',a.year||a.fiscalYear||m.year||'',money(amount)])})})}
  if(kind==='allocation'){out=bs.map(function(b){var name=b.budgetName||b.name||b.account||'Budget',original=n(b.initialAmount||b.originalAmount||b.budgetAmount||total(b)),deptAlloc=n(b.departmentAllocation||b.allocatedAmount),projAlloc=n(b.projectAllocation||b.projectAllocated),spent=deptAlloc+projAlloc;return [name,money(original),money(deptAlloc),money(projAlloc),money(original-spent)]})}
  if(kind==='revision'){var rs=arr('acxBudgetRevisions').concat(arr('budgetRevisions'),arr('acxBudgetRevisionHistory'));out=rs.map(function(r){return [r.date||r.createdAt||'',r.budgetName||r.budgetLine||r.name||'',r.department||'',money(r.before||r.oldAmount),money(r.after||r.newAmount),money(n(r.after||r.newAmount)-n(r.before||r.oldAmount)),r.reason||r.justification||'',r.revisedBy||r.user||'']})}
  if(kind==='transfer'){var ts=arr('acxBudgetTransfers').concat(arr('budgetTransfers'));out=ts.map(function(r){return [r.date||r.createdAt||'',r.fromDepartment||r.from||'',r.toDepartment||r.to||'',money(r.amount),r.reason||'',r.status||r.approvalStatus||'Pending']})}
  if(kind==='approval'){out=bs.map(function(b){return [b.budgetName||b.name||b.account||'',b.department||'',money(total(b)),b.status||'Approved',b.approvedBy||b.approver||'',b.approvedAt||b.approvalDate||'']})}
  if(kind==='limits'){var ds=arr('acxBudgetDepartments'),ls=arr('acxBudgetSpendingLimits').concat(arr('departmentSpendingLimits'));out=ds.map(function(d){var lim=ls.find(function(x){return (x.department||x.departmentName)===d.name}),limit=n(lim&&(lim.limit||lim.amount||lim.spendingLimit)),spent=sum(as.filter(function(a){return actualDepartment(a)===d.name}));return [d.name,money(limit),money(spent),money(limit-spent),limit&&spent>limit?'Exceeded':limit?'Within limit':'Not set']})}
  return out;
 }
 function panel(d){var el=document.createElement('div');el.className='report-view hidden';el.id=d.id;el.innerHTML='<div class="rep-panel-header" style="display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #e5e7eb;padding:10px 0;margin-bottom:12px"><div><h2 style="font-size:18px;font-weight:700;color:#1e3a8a;margin:0">'+esc(d.name)+'</h2><div style="font-size:11px;color:#64748b">Profitability Reports · Budget Management</div></div><div class="rep-actions" style="display:flex;gap:6px"><button type="button" class="px-3 py-2 border rounded text-sm" data-budget-report-refresh>Refresh</button><button type="button" class="px-3 py-2 border rounded text-sm" data-budget-report-csv>Export CSV</button><button type="button" class="px-3 py-2 border rounded text-sm" data-budget-report-print>Print</button></div></div><div class="overflow-x-auto border rounded-lg"><table class="w-full text-sm"><thead class="bg-gray-100"><tr>'+d.cols.map(function(c){return '<th class="border px-3 py-2 text-left">'+esc(c)+'</th>'}).join('')+'</tr></thead><tbody data-budget-report-rows><tr><td colspan="'+d.cols.length+'" class="p-4 text-center text-gray-500">Loading report…</td></tr></tbody><tfoot class="bg-gray-50"><tr><td colspan="'+d.cols.length+'" class="p-2 text-xs text-gray-500" data-budget-report-note>Figures are calculated from saved budget and expenditure records. Missing source records are not estimated.</td></tr></tfoot></table></div>';
  el.addEventListener('click',function(e){if(e.target.matches('[data-budget-report-refresh]'))render(d,el);if(e.target.matches('[data-budget-report-csv]'))csv(d,el);if(e.target.matches('[data-budget-report-print]'))window.print()});return el;}
 function render(d,el){var rows=dataRows(d.kind),body=el.querySelector('[data-budget-report-rows]');body.innerHTML=rows.length?rows.map(function(r){return '<tr>'+r.map(function(c){return '<td class="border px-3 py-2">'+esc(c)+'</td>'}).join('')+'</tr>'}).join(''):'<tr><td colspan="'+d.cols.length+'" class="p-4 text-center text-gray-500">No matching budget records found yet.</td></tr>';var note=el.querySelector('[data-budget-report-note]');if(note)note.textContent=rows.length+' record(s) · Generated '+new Date().toLocaleString()+'. Figures reflect records currently saved in this Books company workspace.';}
 function csv(d,el){var rows=[d.cols].concat(dataRows(d.kind)),text=rows.map(function(r){return r.map(function(v){return '"'+String(v==null?'':v).replace(/"/g,'""')+'"'}).join(',')}).join('\r\n'),blob=new Blob([text],{type:'text/csv;charset=utf-8;'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=d.name.toLowerCase().replace(/[^a-z0-9]+/g,'-')+'.csv';a.click();URL.revokeObjectURL(url)}
 function init(){var nav=document.querySelector('[data-cat="cat_profitabilityReports"]');if(!nav)return;var reports=document.querySelector('.reports-content');if(!reports)return;defs.forEach(function(d){var li=document.createElement('li');li.innerHTML='<span>📁 '+esc(d.name)+'</span>';li.addEventListener('click',function(){if(typeof window.showReport==='function')window.showReport(d.id,li);setTimeout(function(){var el=document.getElementById(d.id);if(el){render(d,el);el.classList.remove('hidden')}},0)});nav.appendChild(li);reports.appendChild(panel(d));});var count=document.querySelector('[data-cat="cat_profitabilityReports"] .rep-cat-count');if(count)count.textContent='(22)';}
 document.addEventListener('DOMContentLoaded',init);
 window.addEventListener('storage',function(e){if(['budgets','actuals','acxBudgetDepartments','acxBudgetRevisions','acxBudgetTransfers','acxBudgetSpendingLimits'].indexOf(e.key)>=0){defs.forEach(function(d){var el=document.getElementById(d.id);if(el&&!el.classList.contains('hidden'))render(d,el)})}});
})();
